/**
 *
 * On Target or Token (AE)
 *
 */

// ------------------------------------------------
// C U S T O M I Z E    T H E    A N I M A T I O N
// ------------------------------------------------
//
const ANIMATION1 = 'blfx.spell.cast.circles1.energy1.blue';
const SCALE1 = 2; // Size of the animation. Default value: 2
const FADEIN1 = 0;
const FADEOUT1 = 0;
const OPACITY1 = 1;
const COLORMATRIX_HUE1 = 0;
const WAIT_UNTIL_FINISHED1 = -200; // Default value: -300
const WAIT_UNTIL_FINISHED_ENABLED1 = true;
const PERSIST1 = false;
const BELOW_TOKENS1 = false;
const ENABLED1 = true;
const SOUND_ENABLED1 = true;
const SOUND1 = 'blfx.sound.spell.cast.heal.1';
const DELAY_SOUND1 = 0; // Default value: 0
const START_TIME_SOUND1 = 0; // Default value: 0
const WAIT_UNTIL_FINISHED_SOUND_ENABLED1 = false;
const WAIT_UNTIL_FINISHED_SOUND1 = 0;

const ANIMATION2 = 'blfx.spell.range.ray.beam1.sinusoidal.intro.orange';
const OPACITY2 = 1;
const COLORMATRIX_HUE2 = 0;
const WAIT_UNTIL_FINISHED2 = -500; // Default value: -100
const WAIT_UNTIL_FINISHED_ENABLED2 = false;
const PERSIST2 = false;
const BELOW_TOKENS2 = false;
const ENABLED2 = true;
const SOUND_ENABLED2 = true;
const SOUND2 = 'blfx.sound.spell.cast.generic.1';
const DELAY_SOUND2 = 0; // Default value: 0
const START_TIME_SOUND2 = 0; // Default value: 0
const WAIT_UNTIL_FINISHED_SOUND_ENABLED2 = false;
const WAIT_UNTIL_FINISHED_SOUND2 = 0;

const ANIMATION3 = 'blfx.spell.misc.shield2.arcane2.mage-armor.loop.blue';
const SCALE3 = 1.85; // Size of the animation. Default value: 2
const FADEIN3 = 0;
const FADEOUT3 = 0;
const OPACITY3 = 1;
const COLORMATRIX_HUE3 = 0;
const DELAY_ANIMATION3 = 0; // Default value: 0
const BELOW_TOKENS3 = false;
const PERSIST3 = true;
const ENABLED3 = true;
const SOUND_ENABLED3 = true;
const SOUND3 = 'blfx.sound.spell.cast.charm_person.3';
const DELAY_SOUND3 = 0; // Default value: 0
const START_TIME_SOUND3 = 0; // Default value: 0
//
// ------------------------------------------------

if (typeof sourceToken === 'undefined' || sourceToken === null) return;
if (typeof targetTokens === 'undefined' || targetTokens === null || targetTokens.length === 0) return; // there have to be a target

const [targetToken] = targetTokens;
const playAnimation2 = sourceToken.id === targetToken.id ? false : true;

// ON SOURCE TOKEN
await new Sequence()
  .sound()
  .playIf(SOUND_ENABLED1)
  .file(SOUND1)
  .delay(DELAY_SOUND1)
  .startTime(START_TIME_SOUND1)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_SOUND_ENABLED1, WAIT_UNTIL_FINISHED_SOUND1])

  .effect()
  .playIf(ENABLED1)
  .file(ANIMATION1)
  .name(`${effect.name}-${effect.id}`)
  .atLocation(sourceToken)
  .scaleToObject(SCALE1)
  .fadeIn(FADEIN1)
  .fadeOut(FADEOUT1)
  .opacity(OPACITY1)
  .filter('ColorMatrix', { hue: COLORMATRIX_HUE1 })
  .belowTokens(BELOW_TOKENS1)
  .tieToDocuments(effect)
  .attachTo(sourceToken)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_ENABLED1, WAIT_UNTIL_FINISHED1])
  .persist(PERSIST1)
  .play();

// FROM SOURCE TO TARGET
await new Sequence()
  .sound()
  .playIf(SOUND_ENABLED2)
  .file(SOUND2)
  .delay(DELAY_SOUND2)
  .startTime(START_TIME_SOUND2)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_SOUND_ENABLED2, WAIT_UNTIL_FINISHED_SOUND2])

  .effect()
  .playIf(ENABLED2 && playAnimation2)
  .file(ANIMATION2)
  .name(`${effect.name}-${effect.id}`)
  .opacity(OPACITY2)
  .filter('ColorMatrix', { hue: COLORMATRIX_HUE2 })
  .belowTokens(BELOW_TOKENS2)
  .atLocation(sourceToken)
  .stretchTo(targetToken, { attachTo: true })
  .tieToDocuments(effect)
  .attachTo(sourceToken)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_ENABLED2, WAIT_UNTIL_FINISHED2])
  .persist(PERSIST2)
  .play();

// ON TARGET
await new Sequence()
  .sound()
  .playIf(SOUND_ENABLED3)
  .file(SOUND3)
  .delay(DELAY_SOUND3)
  .startTime(START_TIME_SOUND3)

  .effect()
  .playIf(ENABLED3)
